    startSealRitual() {
        clearTimeout(this.ritualTimer);
        this.currentPhase = 2;
        this.progress.phase2Complete = true;
        this.saveProgress('phase2-ritual');
        this.hud.innerText = 'Ritual · Selo da Fase 2';
        this.contentArea.innerHTML = `
            <section class="seal-ritual" aria-label="Ritual contemplativo de gravação do selo">
                <header class="ritual-heading">
                    <p class="record-kicker">Segundo Registro concluído</p>
                    <h1>O selo será gravado</h1>
                    <p>Silencie o coração por um instante. A libertação e a aliança agora serão inscritas no manuscrito.</p>
                </header>

                <div class="ritual-manuscript" aria-live="polite">
                    <span class="ritual-imprint" id="ritual-imprint" aria-hidden="true"></span>
                    <img class="ritual-seal inscribing" id="ritual-seal" src="assets/golden_seal_icon.webp" alt="Selo dourado sendo gravado no manuscrito">
                    <p class="ritual-status" id="ritual-status">O selo desce sobre o manuscrito...</p>
                </div>

                <p class="ritual-synthesis" id="ritual-synthesis">
                    <strong>Palavra de síntese</strong>
                    A liberdade recebida conduz à aliança: Deus chama, livra, acompanha e ensina seu povo a caminhar em fidelidade.
                </p>

                <div class="ritual-actions" id="ritual-actions" aria-label="Escolha após o ritual">
                    <button class="choice-button primary" id="btn-contemplate-conquest">Contemplar a conquista</button>
                    <button class="choice-button" id="btn-ritual-path">Voltar ao Caminho dos Manuscritos</button>
                </div>
            </section>
        `;
        audioManager.playSound('unroll');
        this.ritualTimer = setTimeout(() => {
            const seal = document.getElementById('ritual-seal');
            const imprint = document.getElementById('ritual-imprint');
            const status = document.getElementById('ritual-status');
            const synthesis = document.getElementById('ritual-synthesis');
            const actions = document.getElementById('ritual-actions');
            if (!seal || !imprint || !status || !synthesis || !actions) return;
            seal.classList.remove('inscribing');
            seal.classList.add('inscribed');
            imprint.classList.add('revealed');
            this.animateInscription(document.querySelector('.ritual-manuscript'), 'seal-recorded', true);
            status.classList.add('status-inscribed');
            status.textContent = 'Selo gravado · passagem concluída';
            synthesis.classList.add('revealed');
            actions.classList.add('revealed');
            this.progress.phase2Sealed = true;
            this.progress.lastPreservedManuscript = 2;
            this.saveProgress('phase2-conquest');
            audioManager.playSound('success');
            document.getElementById('btn-contemplate-conquest').addEventListener('click', () => this.showPhase2Conquest());
            document.getElementById('btn-ritual-path').addEventListener('click', () => this.showManuscriptPath());
        }, 1150);
    }

